  8	import java.math.BigDecimal;
  9	import java.sql.Connection;
 10	import java.sql.Date;
 11	import java.sql.PreparedStatement;
 12	import java.sql.ResultSet;
 13	import java.sql.SQLException;
 14	import java.sql.Statement;
 15	import java.sql.Types;
 16	import java.time.LocalDate;
 17	import java.util.*;
 18	
 19	public class ReservationService {
 20	    private static final Map<String, Integer> COMPANY_DISCOUNTS = Map.of(
 21	        "TECNOSUL", 12,
 22	        "AGROVALE", 18,
 23	        "FARMAVIDA", 25
 24	    );
 25	
 26	    private static final Map<String, BigDecimal> WEEKEND_PACKAGE_PRICES = Map.of(
 27	        "STANDARD", new BigDecimal("520.00"),
 28	        "DELUXE", new BigDecimal("820.00"),
 29	        "SUITE", new BigDecimal("1200.00")
 30	    );
 31	
 32	    public long createReservation(int roomNumber, String guestName, String guestEmail,
 33	                                  String guestCpf, LocalDate checkIn, LocalDate checkOut,
 34	                                  int guests, RatePlan ratePlan, String companyCode) throws Exception {
 35	        Room room = RoomService.getRoomByNumber(roomNumber);
 36	        if (room == null) {
 37	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
 38	        }
 39	
 40	        if (guests < 1 || guests > room.getCapacity()) {
 41	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
 42	        }
 43	
 44	        if (!checkOut.isAfter(checkIn)) {
 45	            throw new IllegalArgumentException("INVALID_REQUEST");
 46	        }
 47	
 48	        validateRatePlanRules(ratePlan, checkIn, checkOut, companyCode);
 49	
 50	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
 51	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
 52	        }
 53	
 54	        int nights = calculateNights(checkIn, checkOut);
 55	        PricingResult pricing = calculatePrice(room, checkIn, checkOut, nights, ratePlan, companyCode);
 56	
 57	        try (Connection conn = Database.getConnection();
 58	             PreparedStatement stmt = conn.prepareStatement(
 59	                "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests, rate_plan, company_code, nights, subtotal, discount, total, status, amount_paid, refund) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
 60	                Statement.RETURN_GENERATED_KEYS)) {
 61	
 62	            stmt.setInt(1, roomNumber);
 63	            stmt.setString(2, guestName);
 64	            stmt.setString(3, guestEmail);
 65	            stmt.setString(4, guestCpf);
 66	            stmt.setDate(5, Date.valueOf(checkIn));
 67	            stmt.setDate(6, Date.valueOf(checkOut));
 68	            stmt.setInt(7, guests);
 69	            stmt.setString(8, ratePlan.toString());
 70	            stmt.setString(9, companyCode);
 71	            stmt.setInt(10, nights);
 72	            stmt.setBigDecimal(11, pricing.subtotal);
 73	            stmt.setBigDecimal(12, pricing.discount);
 74	            stmt.setBigDecimal(13, pricing.total);
 75	            stmt.setString(14, ReservationStatus.PENDING.toString());
 76	            stmt.setBigDecimal(15, BigDecimal.ZERO);
 77	            stmt.setNull(16, Types.NUMERIC);
 78	
 79	            stmt.executeUpdate();
 80	
 81	            try (ResultSet rs = stmt.getGeneratedKeys()) {
 82	                if (rs.next()) {
 83	                    return rs.getLong(1);
 84	                }
 85	            }
 86	        }
 87	
 88	        throw new RuntimeException("Failed to create reservation");
 89	    }
 90	
 91	    public Reservation getReservation(long id) throws Exception {
 92	        try (Connection conn = Database.getConnection();
 93	             PreparedStatement stmt = conn.prepareStatement(
 94	                "SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests, rate_plan, company_code, nights, subtotal, discount, total, status, amount_paid, refund FROM reservations WHERE id = ?")) {
 95	
 96	            stmt.setLong(1, id);
 97	            try (ResultSet rs = stmt.executeQuery()) {
 98	                if (rs.next()) {
 99	                    return mapReservation(rs);
100	                }
101	            }
102	        }
103	        return null;
104	    }
105	
106	    public void confirmReservation(long id, BigDecimal amountPaid) throws Exception {
107	        Reservation res = getReservation(id);
108	        if (res == null) {
109	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
110	        }
111	
112	        if (res.getStatus() != ReservationStatus.PENDING) {
113	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
114	        }
115	
116	        try (Connection conn = Database.getConnection();
117	             PreparedStatement stmt = conn.prepareStatement(
118	                "UPDATE reservations SET status = ?, amount_paid = ? WHERE id = ?")) {
119	
120	            stmt.setString(1, ReservationStatus.CONFIRMED.toString());
121	            stmt.setBigDecimal(2, amountPaid);
122	            stmt.setLong(3, id);
123	            stmt.executeUpdate();
124	        }
125	    }
126	
127	    public void checkIn(long id) throws Exception {
128	        Reservation res = getReservation(id);
129	        if (res == null) {
130	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
131	        }
132	
133	        if (res.getStatus() != ReservationStatus.CONFIRMED) {
134	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
135	        }
136	
137	        try (Connection conn = Database.getConnection();
138	             PreparedStatement stmt = conn.prepareStatement(
139	                "UPDATE reservations SET status = ? WHERE id = ?")) {
140	
141	            stmt.setString(1, ReservationStatus.CHECKED_IN.toString());
142	            stmt.setLong(2, id);
143	            stmt.executeUpdate();
144	        }
145	    }
146	
147	    public void checkOut(long id) throws Exception {
148	        Reservation res = getReservation(id);
149	        if (res == null) {
150	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
151	        }
152	
153	        if (res.getStatus() != ReservationStatus.CHECKED_IN) {
154	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
155	        }
156	
157	        try (Connection conn = Database.getConnection();
158	             PreparedStatement stmt = conn.prepareStatement(
159	                "UPDATE reservations SET status = ? WHERE id = ?")) {
160	
161	            stmt.setString(1, ReservationStatus.CHECKED_OUT.toString());
162	            stmt.setLong(2, id);
163	            stmt.executeUpdate();
164	        }
165	    }
166	
167	    public void cancelReservation(long id) throws Exception {
168	        Reservation res = getReservation(id);
169	        if (res == null) {
170	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
171	        }
172	
173	        if (res.getStatus() != ReservationStatus.PENDING && res.getStatus() != ReservationStatus.CONFIRMED) {
174	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
175	        }
176	
177	        BigDecimal refund = calculateRefund(res);
178	
179	        try (Connection conn = Database.getConnection();
180	             PreparedStatement stmt = conn.prepareStatement(
181	                "UPDATE reservations SET status = ?, refund = ? WHERE id = ?")) {
182	
183	            stmt.setString(1, ReservationStatus.CANCELLED.toString());
184	            if (refund != null) {
185	                stmt.setBigDecimal(2, refund);
186	            } else {
187	                stmt.setNull(2, Types.NUMERIC);
188	            }
189	            stmt.setLong(3, id);
190	            stmt.executeUpdate();
191	        }
192	    }
193	
194	    private BigDecimal calculateRefund(Reservation res) {
195	        if (res.getStatus() == ReservationStatus.PENDING) {
196	            return null;
197	        }
198	
199	        return switch (res.getRatePlan()) {
200	            case STANDARD -> res.getAmountPaid();
201	            case NON_REFUNDABLE -> BigDecimal.ZERO;
202	            case CORPORATE -> res.getAmountPaid();
203	            case WEEKEND_PACKAGE -> MoneyRounder.round(res.getAmountPaid().multiply(new BigDecimal("0.5")));
204	            case LONG_STAY -> res.getAmountPaid();
205	        };
206	    }
207	
208	    private void validateRatePlanRules(RatePlan ratePlan, LocalDate checkIn, LocalDate checkOut, String companyCode) throws Exception {
209	        switch (ratePlan) {
210	            case CORPORATE:
211	                if (companyCode == null || !COMPANY_DISCOUNTS.containsKey(companyCode)) {
212	                    throw new IllegalArgumentException("INVALID_REQUEST");
213	                }
214	                break;
215	            case WEEKEND_PACKAGE:
216	                if (!isWeekendPackageValid(checkIn, checkOut)) {
217	                    throw new IllegalArgumentException("INVALID_REQUEST");
218	                }
219	                break;
220	            case LONG_STAY:
221	                if (calculateNights(checkIn, checkOut) < 7) {
222	                    throw new IllegalArgumentException("INVALID_REQUEST");
223	                }
224	                break;
225	        }
226	    }
227	
228	    private boolean isWeekendPackageValid(LocalDate checkIn, LocalDate checkOut) {
229	        if (calculateNights(checkIn, checkOut) != 2) {
230	            return false;
231	        }
232	
233	        int dayOfWeek = checkIn.getDayOfWeek().getValue();
234	        int dayOfWeekCheckOut = checkOut.getDayOfWeek().getValue();
235	
236	        return dayOfWeek == 5 && dayOfWeekCheckOut == 7;
237	    }
238	
239	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) throws Exception {
240	        try (Connection conn = Database.getConnection();
241	             PreparedStatement stmt = conn.prepareStatement(
242	                "SELECT COUNT(*) FROM reservations WHERE room_number = ? AND status != 'CANCELLED' AND check_in < ? AND check_out > ?")) {
243	
244	            stmt.setInt(1, roomNumber);
245	            stmt.setDate(2, Date.valueOf(checkOut));
246	            stmt.setDate(3, Date.valueOf(checkIn));
247	
248	            try (ResultSet rs = stmt.executeQuery()) {
249	                rs.next();
250	                return rs.getInt(1) > 0;
251	            }
252	        }
253	    }
254	
255	    private int calculateNights(LocalDate checkIn, LocalDate checkOut) {
256	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
257	    }
258	
259	    private PricingResult calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut,
260	                                        int nights, RatePlan ratePlan, String companyCode) {
261	        return switch (ratePlan) {
262	            case STANDARD -> calculateStandardPrice(room, checkIn, nights);
263	            case NON_REFUNDABLE -> calculateNonRefundablePrice(room, checkIn, nights);
264	            case CORPORATE -> calculateCorporatePrice(room, checkIn, nights, companyCode);
265	            case WEEKEND_PACKAGE -> calculateWeekendPrice(room);
266	            case LONG_STAY -> calculateLongStayPrice(room, checkIn, nights);
267	        };
268	    }
269	
270	    private PricingResult calculateStandardPrice(Room room, LocalDate checkIn, int nights) {
271	        BigDecimal subtotal = BigDecimal.ZERO;
272	
273	        for (int i = 0; i < nights; i++) {
274	            LocalDate nightDate = checkIn.plusDays(i);
275	            BigDecimal rate = room.getNightlyRate();
276	            if (SeasonUtil.isHighSeason(nightDate)) {
277	                rate = MoneyRounder.round(rate.multiply(new BigDecimal("1.20")));
278	            }
279	            subtotal = subtotal.add(rate);
280	        }
281	
282	        subtotal = MoneyRounder.round(subtotal);
283	        return new PricingResult(subtotal, BigDecimal.ZERO, subtotal);
284	    }
285	
286	    private PricingResult calculateNonRefundablePrice(Room room, LocalDate checkIn, int nights) {
287	        PricingResult standard = calculateStandardPrice(room, checkIn, nights);
288	        BigDecimal discount = MoneyRounder.round(standard.subtotal.multiply(new BigDecimal("0.15")));
289	        BigDecimal total = MoneyRounder.round(standard.subtotal.subtract(discount));
290	
291	        return new PricingResult(standard.subtotal, discount, total);
292	    }
293	
294	    private PricingResult calculateCorporatePrice(Room room, LocalDate checkIn, int nights, String companyCode) {
295	        PricingResult standard = calculateStandardPrice(room, checkIn, nights);
296	        int discountPercent = COMPANY_DISCOUNTS.get(companyCode);
297	        BigDecimal discount = MoneyRounder.round(standard.subtotal.multiply(new BigDecimal(discountPercent).divide(new BigDecimal("100"), 10, java.math.RoundingMode.HALF_EVEN)));
298	        BigDecimal total = MoneyRounder.round(standard.subtotal.subtract(discount));
299	
300	        return new PricingResult(standard.subtotal, discount, total);
301	    }
302	
303	    private PricingResult calculateWeekendPrice(Room room) {
304	        BigDecimal price = WEEKEND_PACKAGE_PRICES.get(room.getType().toString());
305	        return new PricingResult(price, BigDecimal.ZERO, price);
306	    }
307	
308	    private PricingResult calculateLongStayPrice(Room room, LocalDate checkIn, int nights) {
309	        BigDecimal subtotal = BigDecimal.ZERO;
310	
311	        for (int i = 0; i < nights; i++) {
312	            LocalDate nightDate = checkIn.plusDays(i);
313	            BigDecimal rate = room.getNightlyRate();
314	            if (SeasonUtil.isHighSeason(nightDate)) {
315	                rate = MoneyRounder.round(rate.multiply(new BigDecimal("1.20")));
316	            }
317	            subtotal = subtotal.add(rate);
318	        }
319	
320	        subtotal = MoneyRounder.round(subtotal);
321	        BigDecimal discount = MoneyRounder.round(subtotal.multiply(new BigDecimal("0.10")));
322	        BigDecimal total = MoneyRounder.round(subtotal.subtract(discount));
323	
324	        return new PricingResult(subtotal, discount, total);
325	    }
326	
327	    private Reservation mapReservation(ResultSet rs) throws SQLException {
328	        long id = rs.getLong("id");
329	        int roomNumber = rs.getInt("room_number");
330	        String guestName = rs.getString("guest_name");
331	        String guestEmail = rs.getString("guest_email");
332	        String guestCpf = rs.getString("guest_cpf");
333	        LocalDate checkIn = rs.getDate("check_in").toLocalDate();
334	        LocalDate checkOut = rs.getDate("check_out").toLocalDate();
335	        int guests = rs.getInt("guests");
336	        RatePlan ratePlan = RatePlan.valueOf(rs.getString("rate_plan"));
337	        String companyCode = rs.getString("company_code");
338	        int nights = rs.getInt("nights");
339	        BigDecimal subtotal = rs.getBigDecimal("subtotal");
340	        BigDecimal discount = rs.getBigDecimal("discount");
341	        BigDecimal total = rs.getBigDecimal("total");
342	        ReservationStatus status = ReservationStatus.valueOf(rs.getString("status"));
343	        BigDecimal amountPaid = rs.getBigDecimal("amount_paid");
344	        BigDecimal refund = rs.getBigDecimal("refund");
345	
346	        return new Reservation(id, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut,
347	                              guests, ratePlan, companyCode, nights, subtotal, discount, total,
348	                              status, amountPaid, refund);
349	    }
350	
351	    private static class PricingResult {
352	        BigDecimal subtotal;
353	        BigDecimal discount;
354	        BigDecimal total;
355	
356	        PricingResult(BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
357	            this.subtotal = subtotal;
358	            this.discount = discount;
359	            this.total = total;
360	        }
361	    }
362	}

