 12	import java.math.BigDecimal;
 13	import java.time.LocalDate;
 14	import java.time.format.DateTimeFormatter;
 15	
 16	public class ReservationHandler {
 17	    private static final Gson gson = new Gson();
 18	    private static final DateTimeFormatter dateFormatter = DateTimeFormatter.ISO_DATE;
 19	    private static final ReservationService reservationService = new ReservationService();
 20	
 21	    public static void createReservation(Context ctx) {
 22	        try {
 23	            JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
 24	
 25	            if (!validateCreateRequest(body, ctx)) {
