 36	            RatePlan ratePlan = RatePlan.valueOf(body.get("ratePlan").getAsString());
 37	            String companyCode = body.has("companyCode") && !body.get("companyCode").isJsonNull() ?
 38	                                body.get("companyCode").getAsString() : null;
 39	
 40	            long reservationId = reservationService.createReservation(
 41	                roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan, companyCode
 42	            );
 43	
 44	            Reservation res = reservationService.getReservation(reservationId);
 45	            ctx.status(201);
 46	            ctx.json(serializeReservation(res));
 47	
 48	        } catch (IllegalArgumentException e) {
 49	            handleError(ctx, e.getMessage());
 50	        } catch (Exception e) {
 51	            ctx.status(400);
 52	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
 53	        }
 54	    }
