 56	    public static void getReservation(Context ctx) {
 57	        try {
 58	            long id = Long.parseLong(ctx.pathParam("id"));
 59	            Reservation res = reservationService.getReservation(id);
 60	
 61	            if (res == null) {
 62	                ctx.status(404);
 63	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
 64	                return;
 65	            }
 66	
 67	            ctx.json(serializeReservation(res));
 68	
 69	        } catch (NumberFormatException e) {
 70	            ctx.status(404);
 71	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
 72	        } catch (Exception e) {
 73	            ctx.status(500);
