 75	        }
 76	    }
 77	
 78	    public static void confirmReservation(Context ctx) {
 79	        try {
 80	            long id = Long.parseLong(ctx.pathParam("id"));
 81	            JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
 82	
 83	            if (!body.has("amountPaid") || body.get("amountPaid").isJsonNull()) {
