121	            }
122	
123	            ctx.json(serializeReservation(res));
124	
125	        } catch (IllegalArgumentException e) {
126	            handleError(ctx, e.getMessage());
127	        } catch (Exception e) {
128	            ctx.status(500);
129	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Internal server error"));
130	        }
131	    }
132	
133	    public static void checkIn(Context ctx) {
134	        try {
135	            long id = Long.parseLong(ctx.pathParam("id"));
136	            reservationService.checkIn(id);
137	
138	            Reservation res = reservationService.getReservation(id);
139	            if (res == null) {
140	                ctx.status(404);
141	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
