155	    public static void checkOut(Context ctx) {
156	        try {
157	            long id = Long.parseLong(ctx.pathParam("id"));
158	            reservationService.checkOut(id);
159	
160	            Reservation res = reservationService.getReservation(id);
161	            if (res == null) {
162	                ctx.status(404);
163	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
164	                return;
165	            }
166	
167	            Room room = RoomService.getRoomByNumber(res.getRoomNumber());
168	            ReservationDocument doc = new ReservationDocument(
169	                res.getId(),
170	                res.getGuestName(),
171	                res.getGuestCpf(),
172	                res.getRoomNumber(),
173	                room.getType().toString(),
174	                res.getCheckIn(),
175	                res.getCheckOut(),
176	                res.getNights(),
177	                res.getSubtotal(),
178	                res.getDiscount(),
179	                res.getTotal()
180	            );
181	
182	            ctx.json(doc);
183	
184	        } catch (IllegalArgumentException e) {
185	            handleError(ctx, e.getMessage());
186	        } catch (Exception e) {
187	            ctx.status(500);
188	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Internal server error"));
189	        }
190	    }
191	
192	    public static void getDocument(Context ctx) {
193	        try {
194	            long id = Long.parseLong(ctx.pathParam("id"));
195	            Reservation res = reservationService.getReservation(id);
196	
197	            if (res == null) {
198	                ctx.status(404);
199	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
200	                return;
201	            }
202	
203	            if (res.getAmountPaid() == null || res.getAmountPaid().compareTo(BigDecimal.ZERO) == 0) {
204	                ctx.status(404);
205	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Document not found"));
206	                return;
207	            }
208	
209	            Room room = RoomService.getRoomByNumber(res.getRoomNumber());
210	            ReservationDocument doc = new ReservationDocument(
211	                res.getId(),
212	                res.getGuestName(),
213	                res.getGuestCpf(),
214	                res.getRoomNumber(),
215	                room.getType().toString(),
216	                res.getCheckIn(),
217	                res.getCheckOut(),
218	                res.getNights(),
219	                res.getSubtotal(),
220	                res.getDiscount(),
221	                res.getTotal()
222	            );
223	
224	            ctx.json(doc);
225	
226	        } catch (NumberFormatException e) {
227	            ctx.status(404);
228	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
229	        } catch (Exception e) {
230	            ctx.status(500);
231	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Internal server error"));
232	        }
233	    }
234	
235	    private static void sendConfirmationEmail(Reservation res) throws Exception {
236	        Room room = RoomService.getRoomByNumber(res.getRoomNumber());
237	
238	        String receipt = formatReceipt(res, room);
239	
240	        String emailBody = String.format(
241	            "Olá, %s!\n\n" +
242	            "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n" +
243	            "%s\n\n" +
244	            "A entrada é a partir das 14h, e a saída, até as 12h.\n" +
245	            "Até breve!",
246	            res.getGuestName(),
247	            receipt
248	        );
249	
250	        MessageService.sendMessage("EMAIL", res.getGuestEmail(), "Reserva confirmada - Pousada Maré Alta", emailBody);
251	    }
252	
253	    private static String formatReceipt(Reservation res, Room room) {
254	        String nightsStr = res.getNights() == 1 ? "1 diária" : res.getNights() + " diárias";
255	        LocalDate checkIn = res.getCheckIn();
256	        LocalDate checkOut = res.getCheckOut();
257	
258	        StringBuilder receipt = new StringBuilder();
259	        receipt.append(String.format("Comprovante de reserva nº %d\n", res.getId()));
260	        receipt.append(String.format("Hóspede: %s (CPF %s)\n", res.getGuestName(), formatCpf(res.getGuestCpf())));
261	        receipt.append(String.format("Quarto: %d (%s)\n", res.getRoomNumber(), room.getType()));
262	        receipt.append(String.format("Entrada: %s | Saída: %s | %s\n",
263	            formatDate(checkIn), formatDate(checkOut), nightsStr));
264	        receipt.append(String.format("Diárias: R$ %s\n", formatMoney(res.getSubtotal())));
265	
266	        if (res.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
267	            receipt.append(String.format("Desconto: R$ %s\n", formatMoney(res.getDiscount())));
268	        }
269	
270	        receipt.append(String.format("Total: R$ %s", formatMoney(res.getTotal())));
271	
272	        return receipt.toString();
273	    }
274	
275	    private static String formatDate(LocalDate date) {
276	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
277	    }
278	
279	    private static String formatMoney(BigDecimal amount) {
280	        return String.format("%.2f", amount).replace(".", ",");
281	    }
282	
283	    private static String formatCpf(String cpf) {
284	        if (cpf.length() != 11) return cpf;
285	        return String.format("%s.%s.%s-%s",
286	            cpf.substring(0, 3),
287	            cpf.substring(3, 6),
288	            cpf.substring(6, 9),
289	            cpf.substring(9)
290	        );
291	    }
292	
293	    private static Object serializeReservation(Reservation res) {
294	        JsonObject json = new JsonObject();
295	        json.addProperty("id", res.getId());
296	        json.addProperty("roomNumber", res.getRoomNumber());
297	        json.addProperty("guestName", res.getGuestName());
298	        json.addProperty("guestEmail", res.getGuestEmail());
299	        json.addProperty("guestCpf", res.getGuestCpf());
300	        json.addProperty("checkIn", res.getCheckIn().toString());
301	        json.addProperty("checkOut", res.getCheckOut().toString());
302	        json.addProperty("guests", res.getGuests());
303	        json.addProperty("ratePlan", res.getRatePlan().toString());
304	        json.addProperty("nights", res.getNights());
305	        json.addProperty("subtotal", res.getSubtotal().doubleValue());
306	        json.addProperty("discount", res.getDiscount().doubleValue());
307	        json.addProperty("total", res.getTotal().doubleValue());
308	        json.addProperty("status", res.getStatus().toString());
309	        json.addProperty("amountPaid", res.getAmountPaid().doubleValue());
310	        if (res.getRefund() != null) {
311	            json.addProperty("refund", res.getRefund().doubleValue());
312	        } else {
313	            json.add("refund", null);
314	        }
315	        return json;
316	    }
317	
318	    private static void handleError(Context ctx, String errorCode) {
319	        switch (errorCode) {
320	            case "ROOM_NOT_FOUND":
321	                ctx.status(404);
322	                ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
323	                break;
324	            case "RESERVATION_NOT_FOUND":
325	                ctx.status(404);
326	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
327	                break;
328	            case "ROOM_UNAVAILABLE":
329	                ctx.status(409);
330	                ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is unavailable for the requested dates"));
331	                break;
332	            case "CAPACITY_EXCEEDED":
333	                ctx.status(422);
334	                ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", "Too many guests for this room"));
335	                break;
336	            case "OPERATION_NOT_ALLOWED":
337	                ctx.status(409);
338	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for this reservation state"));
339	                break;
340	            default:
341	                ctx.status(400);
342	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
343	        }
344	    }
345	
346	    private static boolean validateCreateRequest(JsonObject body, Context ctx) {
347	        if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
348	            !body.has("guestCpf") || !body.has("checkIn") || !body.has("checkOut") ||
349	            !body.has("guests") || !body.has("ratePlan")) {
350	            ctx.status(400);
351	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
352	            return false;
353	        }
354	        return true;
355	    }
356	}

