279	    private static String formatMoney(BigDecimal amount) {
280	        return String.format("%.2f", amount).replace(".", ",");
281	    }
282	
283	    private static String formatCpf(String cpf) {
284	        if (cpf.length() != 11) return cpf;
285	        return String.format("%s.%s.%s-%s",
286	            cpf.substring(0, 3),
287	            cpf.substring(3, 6),
288	            cpf.substring(6, 9),
289	            cpf.substring(9)
290	        );
291	    }
