293	    private static Object serializeReservation(Reservation res) {
294	        JsonObject json = new JsonObject();
295	        json.addProperty("id", res.getId());
296	        json.addProperty("roomNumber", res.getRoomNumber());
297	        json.addProperty("guestName", res.getGuestName());
298	        json.addProperty("guestEmail", res.getGuestEmail());
299	        json.addProperty("guestCpf", res.getGuestCpf());
300	        json.addProperty("checkIn", res.getCheckIn().toString());
301	        json.addProperty("checkOut", res.getCheckOut().toString());
302	        json.addProperty("guests", res.getGuests());
303	        json.addProperty("ratePlan", res.getRatePlan().toString());
304	        json.addProperty("nights", res.getNights());
305	        json.addProperty("subtotal", res.getSubtotal().doubleValue());
306	        json.addProperty("discount", res.getDiscount().doubleValue());
307	        json.addProperty("total", res.getTotal().doubleValue());
308	        json.addProperty("status", res.getStatus().toString());
309	        json.addProperty("amountPaid", res.getAmountPaid().doubleValue());
310	        if (res.getRefund() != null) {
311	            json.addProperty("refund", res.getRefund().doubleValue());
312	        } else {
313	            json.add("refund", null);
314	        }
315	        return json;
316	    }
317	
318	    private static void handleError(Context ctx, String errorCode) {
319	        switch (errorCode) {
320	            case "ROOM_NOT_FOUND":
321	                ctx.status(404);
322	                ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
323	                break;
324	            case "RESERVATION_NOT_FOUND":
325	                ctx.status(404);
326	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
327	                break;
328	            case "ROOM_UNAVAILABLE":
329	                ctx.status(409);
330	                ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is unavailable for the requested dates"));
331	                break;
332	            case "CAPACITY_EXCEEDED":
333	                ctx.status(422);
334	                ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", "Too many guests for this room"));
335	                break;
336	            case "OPERATION_NOT_ALLOWED":
337	                ctx.status(409);
338	                ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for this reservation state"));
339	                break;
340	            default:
341	                ctx.status(400);
342	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
343	        }
344	    }
345	
346	    private static boolean validateCreateRequest(JsonObject body, Context ctx) {
347	        if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
348	            !body.has("guestCpf") || !body.has("checkIn") || !body.has("checkOut") ||
349	            !body.has("guests") || !body.has("ratePlan")) {
350	            ctx.status(400);
351	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
352	            return false;
353	        }
354	        return true;
355	    }
356	}

