    77	        try (Connection conn = Database.getConnection();
    78	             PreparedStatement stmt = conn.prepareStatement(
    79	                "SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests, rate_plan, company_code, nights, subtotal, discount, total, status, amount_paid, refund FROM reservations WHERE check_in <= ? AND check_out > ? AND status IN ('CHECKED_IN', 'CHECKED_OUT', 'CONFIRMED') ORDER BY room_number")) {
    80	
    81	            stmt.setDate(1, Date.valueOf(date));
    82	            stmt.setDate(2, Date.valueOf(date));
    83	
