    95	    private static List<Reservation> getReservationsStartingInMonth(YearMonth month) throws Exception {
    96	        List<Reservation> reservations = new ArrayList<>();
    97	
    98	        LocalDate start = month.atDay(1);
    99	        LocalDate end = month.atEndOfMonth().plusDays(1);
   100	
   101	        try (Connection conn = Database.getConnection();
   102	             PreparedStatement stmt = conn.prepareStatement(
   103	                "SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, guests, rate_plan, company_code, nights, subtotal, discount, total, status, amount_paid, refund FROM reservations WHERE check_in >= ? AND check_in < ? AND (amount_paid > 0 OR refund > 0) ORDER BY check_in, id")) {
   104	
   105	            stmt.setDate(1, Date.valueOf(start));
   106	            stmt.setDate(2, Date.valueOf(end));
   107	
   108	            try (ResultSet rs = stmt.executeQuery()) {
   109	                while (rs.next()) {
   110	                    Reservation res = mapReservation(rs);
   111	                    reservations.add(res);
   112	                }
   113	            }
   114	        }
   115	
   116	        return reservations;
   117	    }
