   119	    private static Reservation mapReservation(ResultSet rs) throws SQLException {
   120	        return new Reservation(
   121	            rs.getLong("id"),
   122	            rs.getInt("room_number"),
   123	            rs.getString("guest_name"),
   124	            rs.getString("guest_email"),
   125	            rs.getString("guest_cpf"),
