    22	        csv.append("room,type,reservation,check_in,check_out\n");
    23	
    24	        List<Reservation> reservations = getReservationsForNight(date);
    25	        int occupied = 0;
    26	
    27	        for (Reservation res : reservations) {
    28	            csv.append(String.format("%d,%s,%d,%s,%s\n",
    29	                res.getRoomNumber(),
    30	                RoomService.getRoomByNumber(res.getRoomNumber()).getType(),
    31	                res.getId(),
    32	                res.getCheckIn().toString(),
    33	                res.getCheckOut().toString()
    34	            ));
    35	            occupied++;
    36	        }
    37	
    38	        csv.append(String.format("total,%d/5\n", occupied));
    39	
    40	        return csv.toString();
    41	    }
    42	
    43	    public static String getRevenueReport(YearMonth month) throws Exception {
    44	        StringBuilder csv = new StringBuilder();
    45	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    46	
    47	        List<Reservation> reservations = getReservationsStartingInMonth(month);
    48	        BigDecimal total = BigDecimal.ZERO;
    49	
    50	        for (Reservation res : reservations) {
    51	            BigDecimal amount = res.getAmountPaid();
    52	            if (res.getRefund() != null && res.getRefund().compareTo(BigDecimal.ZERO) > 0) {
    53	                amount = MoneyRounder.round(amount.subtract(res.getRefund()));
    54	            }
    55	
    56	            csv.append(String.format("%d,%d,%s,%s,%s,%.2f\n",
    57	                res.getId(),
    58	                res.getRoomNumber(),
    59	                res.getCheckIn().toString(),
    60	                res.getCheckOut().toString(),
    61	                res.getStatus(),
    62	                amount.doubleValue()
    63	            ));
    64	
    65	            total = total.add(amount);
    66	        }
    67	
    68	        total = MoneyRounder.round(total);
    69	        csv.append(String.format("total,%.2f\n", total.doubleValue()));
    70	
    71	        return csv.toString();
    72	    }
